LIB.push(
{t:"Il paradosso della scelta",c:"rag",tg:"Troppe opzioni possono renderci meno capaci di scegliere e meno soddisfatti.",d:2,
sp:"Lo psicologo Barry Schwartz ha descritto il paradosso della scelta: pensiamo che avere più opzioni ci renda più liberi e felici, ma oltre un certo punto le troppe possibilità ci bloccano, ci fanno rimandare e ci lasciano meno soddisfatti di ciò che scegliamo, perché immaginiamo sempre che un'altra opzione sarebbe stata migliore.",
ap:["In un famoso esperimento in un supermercato, un banco con 24 marmellate attirava più persone di uno con 6, ma vendeva molto meno. Davanti a troppe alternative la decisione diventa faticosa e il rimpianto per le opzioni scartate cresce. I risultati di questo esperimento non si sono sempre ripetuti, ma l'idea di fondo resta utile.","Per difenderti, riduci le opzioni prima di scegliere: fissa dei criteri, guarda solo tre alternative, accetta una scelta abbastanza buona invece della perfetta. E dopo aver deciso, smetti di confrontare."],
ri:[["Indecisione davanti a troppe opzioni","Passi ore a confrontare prodotti."],["Rimpianto dopo l'acquisto","Pensi che un'altra scelta sarebbe stata migliore."],["Rimandare la decisione","Aspetti di avere tutte le informazioni."]],
es:[["Acquisti","Per comprare un aspirapolvere guardi solo i tre più venduti con buone recensioni. Scegli in 20 minuti invece che in una settimana."],["Lavoro","Un ristorante riduce il menu da 60 a 15 piatti. I clienti ordinano prima e sono più soddisfatti."]],
ex:["Per la prossima scelta, limitati a tre opzioni.","Scrivi in anticipo tre criteri e scegli la prima opzione che li soddisfa.","Dopo una decisione, evita di guardare le alternative per un mese."],
q:["Quante opzioni mi servono davvero?","Quali criteri contano per me?","Sto cercando il meglio o il buono abbastanza?"],
er:"Pensare che più scelta sia sempre meglio.",
qz:[["Cosa dice il paradosso della scelta?",["Più opzioni rendono sempre più felici","Troppe opzioni possono bloccare e ridurre la soddisfazione","Bisogna avere una sola opzione","Le scelte non contano"],1,"Oltre un certo punto le opzioni pesano."],["Come difendersi dal paradosso?",["Guardare ogni opzione","Ridurre le opzioni e fissare criteri in anticipo","Non scegliere mai","Chiedere a tutti"],1,"Meno opzioni, decisione più facile."]]},

{t:"La legge di Parkinson",c:"app",tg:"Il lavoro si espande fino a occupare tutto il tempo disponibile.",d:1,
sp:"Nel 1955 lo storico Cyril Northcote Parkinson scrisse ironicamente che il lavoro si espande fino a riempire tutto il tempo a disposizione. Se hai una settimana per una relazione, ci metterai una settimana; se hai un giorno, la finirai in un giorno. Il modello ti invita a fissare scadenze più strette e ragionevoli per non sprecare tempo.",
ap:["Con molto tempo, aggiungiamo dettagli inutili, rimandiamo, ci perdiamo in attività secondarie. La stessa legge vale per i soldi (le spese crescono con il reddito) e per lo spazio (gli oggetti riempiono la casa).","Per usarla: dai a ogni attività un tempo massimo, più corto di quello che ti viene istintivo, e lavora per blocchi. Attenzione però a non esagerare: scadenze impossibili portano a stress ed errori."],
ri:[["Lavori che durano fino alla scadenza","Finisci sempre all'ultimo momento."],["Riunioni lunghe un'ora per abitudine","Anche se ne basterebbero venti minuti."],["Spese che crescono con lo stipendio","Più guadagni, più spendi."]],
es:[["Lavoro","Le riunioni settimanali passano da 60 a 25 minuti. Si decide esattamente le stesse cose."],["Casa","Ti dai 30 minuti per pulire la cucina invece di «tutta la mattina». Finisci in mezz'ora e hai la mattina libera."]],
ex:["Per tre attività di questa settimana, fissa un tempo massimo più breve del solito.","Riduci la durata predefinita delle tue riunioni o telefonate.","Quando ricevi un aumento, decidi in anticipo quanta parte risparmiare."],
q:["Quanto tempo serve davvero per questo?","Sto riempiendo il tempo con dettagli inutili?","Che scadenza più corta posso darmi?"],
er:"Fissare scadenze così strette da compromettere la qualità.",
qz:[["Cosa dice la legge di Parkinson?",["Il lavoro diminuisce col tempo","Il lavoro si espande fino a occupare il tempo disponibile","Bisogna lavorare di più","Le scadenze non servono"],1,"Più tempo hai, più ne usi."],["Come si usa la legge a proprio vantaggio?",["Dandosi più tempo","Fissando un tempo massimo più breve e ragionevole","Ignorando le scadenze","Lavorando di notte"],1,"Una scadenza stretta concentra il lavoro."]]},

{t:"I principi di progetto di Patil",c:"lav",tg:"Trasforma un problema difficile in uno più semplice, parti piccolo e usa le persone dove le macchine non bastano.",d:3,
sp:"DJ Patil, primo responsabile dei dati del governo degli Stati Uniti, ha descritto un approccio ai progetti basati sui dati che chiamava «data jujitsu»: come nel judo, invece di affrontare un problema difficile di petto, lo si trasforma in uno più facile da risolvere. I suoi principi pratici: parti dal problema dell'utente, costruisci in piccolo e in fretta, e usa l'aiuto delle persone dove gli algoritmi non bastano ancora.",
ap:["Un esempio tipico: invece di costruire un sistema perfetto che indovina i contatti di una persona, si mostra un suggerimento semplice e si lascia che l'utente lo corregga. Il prodotto funziona subito, raccoglie dati utili e migliora nel tempo. La perfezione iniziale non serve se il sistema impara dall'uso.","Fuori dall'informatica, l'idea è: quando un problema sembra troppo difficile, chiediti se esiste una versione più semplice che risolve gran parte del bisogno, e dove una persona può fare ciò che un sistema automatico non sa ancora fare."],
ri:[["Problema che sembra impossibile","Si cerca la soluzione perfetta e totale."],["Automazione a tutti i costi","Si vuole eliminare ogni intervento umano."],["Progetti lunghissimi","Mesi di lavoro prima di vedere un risultato."]],
es:[["Lavoro","Un negozio vuole un sistema che consigli i prodotti. Invece di un algoritmo complesso, parte da una lista «i più comprati insieme» e la fa rivedere ogni settimana a una commessa esperta."],["Casa","Organizzare tutte le foto di famiglia sembra impossibile. Lo rendi più semplice: solo una cartella per anno, e un nipote aiuta con le foto più vecchie."]],
ex:["Per un problema difficile, scrivi una versione più semplice che risolva almeno metà del bisogno.","Individua un punto in cui una persona può fare meglio di uno strumento automatico.","Costruisci in una settimana una prima versione da far provare."],
q:["Esiste una versione più semplice di questo problema?","Dove una persona può aiutare dove il sistema non basta?","Qual è la versione più piccola che posso provare subito?"],
er:"Accontentarsi della versione semplice anche quando il problema richiede di più.",
qz:[["Cosa significa «data jujitsu»?",["Combattere con i dati","Trasformare un problema difficile in uno più facile da risolvere","Raccogliere più dati possibile","Eliminare le persone dai progetti"],1,"Come nel judo, si sfrutta la forza del problema."],["Qual è un principio dell'approccio di Patil?",["Automatizzare tutto subito","Usare le persone dove gli algoritmi non bastano ancora","Aspettare dati perfetti","Lavorare in segreto"],1,"Persone e sistemi si completano."]]},

{t:"L'euristica del picco e del finale",c:"rag",tg:"Ricordiamo un'esperienza soprattutto per il momento più intenso e per come finisce.",d:2,
sp:"Daniel Kahneman ha scoperto che non ricordiamo un'esperienza come la media di tutti i momenti, ma soprattutto per due istanti: il picco (il momento più intenso, bello o brutto) e il finale. In uno studio, pazienti che facevano un esame medico doloroso ricordavano meglio un esame più lungo che finiva con una parte meno dolorosa rispetto a uno più breve che finiva nel momento peggiore.",
ap:["La durata conta poco nel ricordo. Una vacanza bellissima con un ultimo giorno disastroso viene ricordata peggio; un pranzo normale con un dolce speciale alla fine viene ricordato bene. Questo vale per servizi, eventi, lezioni, incontri.","Per usarlo, cura il momento più alto e il finale di ciò che offri o vivi: chiudi le riunioni con un risultato chiaro, termina le lezioni con un successo, saluta gli ospiti con un gesto speciale. E nel valutare le tue esperienze, ricorda che la memoria è distorta."],
ri:[["Ricordi distorti","Un brutto finale rovina il ricordo di una bella esperienza."],["Eventi senza un momento speciale","Tutto è medio, niente resta."],["Chiusure trascurate","Le cose finiscono in fretta e male."]],
es:[["Lavoro","Un albergo offre un dolce in camera l'ultima sera e aiuta con i bagagli. Le recensioni migliorano senza cambiare altro."],["Famiglia","Dopo una giornata faticosa al parco con i bambini, finite con un gelato. Tutti la ricordano come una bella giornata."]],
ex:["Nel prossimo incontro che organizzi, prepara un momento speciale e una buona chiusura.","Ripensa a un'esperienza che ricordi male: è stato il finale a rovinarla?","Termina la tua giornata di lavoro con un piccolo successo o una cosa piacevole."],
q:["Qual è il momento più intenso di questa esperienza?","Come finisce?","Come posso migliorare il picco o il finale?"],
er:"Trascurare tutto il resto pensando che contino solo picco e finale.",
qz:[["Cosa ricordiamo soprattutto di un'esperienza secondo il modello?",["La media di tutti i momenti","Il momento più intenso e il finale","Solo l'inizio","La durata"],1,"Picco e finale dominano il ricordo."],["Come migliorare il ricordo di un evento?",["Renderlo più lungo","Curare un momento speciale e la conclusione","Renderlo più breve","Non cambiare nulla"],1,"Picco e finale pesano di più."]]},

{t:"L'effetto Peltzman",c:"sis",tg:"Quando ci sentiamo più protetti, tendiamo a correre più rischi.",d:2,
sp:"L'economista Sam Peltzman studiò l'effetto delle leggi sulla sicurezza delle auto negli anni Settanta e osservò che i guidatori, sentendosi più protetti da cinture e nuove protezioni, tendevano a guidare in modo più rischioso. In parte il beneficio della sicurezza veniva compensato da comportamenti più imprudenti. Il fenomeno è chiamato anche compensazione del rischio.",
ap:["Lo stesso schema si vede in molti campi: chi indossa protezioni nello sport può giocare in modo più duro, chi ha l'antivirus può cliccare su link sospetti, chi ha un'assicurazione può essere meno prudente. Gli studi successivi hanno mostrato che l'effetto esiste ma raramente annulla del tutto i benefici delle protezioni.","Il modello non dice di rinunciare alla sicurezza, ma di prevedere come cambierà il comportamento delle persone quando si sentono protette. Chiediti: questa protezione mi sta rendendo più imprudente?"],
ri:[["Sicurezza che porta imprudenza","Ti senti protetto e rischi di più."],["Regole che non riducono i danni","Le persone si adattano e compensano."],["Fiducia eccessiva negli strumenti","Lo strumento pensa per te."]],
es:[["Strada","Con un'auto piena di sensori di sicurezza, un guidatore si distrae di più con il telefono. Si accorge del rischio e mette il telefono nel cassetto."],["Salute","Chi prende un integratore «che protegge» mangia peggio. L'integratore non compensa la dieta."]],
ex:["Pensa a una protezione che usi (assicurazione, strumento, regola): ti rende più imprudente in qualcosa?","Prima di introdurre una nuova regola di sicurezza, chiediti come le persone potrebbero compensarla.","Questa settimana usa una protezione senza cambiare il tuo comportamento prudente."],
q:["Questa protezione mi sta facendo rischiare di più?","Come cambieranno le persone quando si sentiranno protette?","Il beneficio netto è ancora positivo?"],
er:"Usare l'effetto come scusa per rifiutare le misure di sicurezza.",
qz:[["Cosa osservò Peltzman?",["Le cinture non servono","Le persone più protette tendevano a guidare in modo più rischioso","Le auto sono pericolose","Le leggi sono inutili"],1,"La protezione cambia il comportamento."],["Cosa suggerisce il modello?",["Eliminare le protezioni","Prevedere come le persone compenseranno il rischio","Fidarsi solo degli strumenti","Ignorare le regole"],1,"Bisogna considerare l'adattamento del comportamento."]]},

{t:"Dare spazio a un cambiamento d'idea",c:"rag",tg:"Crea le condizioni per cui tu e gli altri possiate cambiare idea senza perdere la faccia.",d:2,
sp:"Cambiare idea è difficile, soprattutto davanti agli altri: sembra una sconfitta. Per questo molte persone difendono posizioni sbagliate pur di non ammettere l'errore. Il modello ti invita a lasciare spazio, a te stesso e agli altri, per cambiare idea con dignità: offrire nuove informazioni invece di attacchi, e trattare il cambiamento come un segno di intelligenza.",
ap:["Lo psicologo Adam Grant suggerisce di pensare come uno scienziato: le opinioni sono ipotesi da aggiornare, non parti della propria identità. Un'idea simile è «opinioni forti, tenute con leggerezza»: prendi posizione, ma sii pronto a cambiarla davanti a prove migliori.","Per aiutare gli altri a cambiare idea, evita di umiliarli, riconosci ciò che c'è di giusto nella loro posizione, offri informazioni nuove che permettano di dire «con questi dati, cambio idea». Un antico consiglio militare dice di lasciare sempre al nemico un ponte d'oro per ritirarsi."],
ri:[["Discussioni dove nessuno cede","Ognuno difende la propria posizione a ogni costo."],["Paura di sembrare incoerenti","Non cambi idea per non perdere la faccia."],["Identità legata alle opinioni","Una critica all'idea sembra un attacco alla persona."]],
es:[["Lavoro","Un collega difende un piano sbagliato. Invece di dirgli che ha torto, porti dati nuovi e dici: «Con queste informazioni anche io avrei proposto il tuo piano. Cosa ne pensi adesso?». Cambia idea."],["Te stesso","Durante una cena dici: «Ho cambiato idea su questo, ho letto qualcosa che non sapevo». Gli altri ti ascoltano con più rispetto."]],
ex:["Scrivi un'opinione su cui hai cambiato idea negli ultimi anni e cosa ti ha convinto.","Nella prossima discussione, riconosci ad alta voce un punto giusto dell'altro.","Prima di una conversazione difficile, prepara un modo per lasciare all'altro una via d'uscita dignitosa."],
q:["Questa opinione è un'ipotesi o una parte della mia identità?","Cosa mi farebbe cambiare idea?","Sto lasciando all'altro un modo dignitoso per cambiare idea?"],
er:"Cambiare idea a ogni obiezione, senza mai prendere posizione.",
qz:[["Come aiutare qualcuno a cambiare idea?",["Umiliandolo davanti a tutti","Offrendo informazioni nuove e una via d'uscita dignitosa","Ripetendo la propria posizione più forte","Ignorandolo"],1,"Le persone cambiano idea più facilmente senza perdere la faccia."],["Cosa significa «opinioni forti, tenute con leggerezza»?",["Non avere opinioni","Prendere posizione ma essere pronti a cambiarla davanti a prove migliori","Non cambiare mai idea","Cambiare idea sempre"],1,"Si aggiorna l'opinione con le prove."]]},

{t:"Personas: profili utili di utenti",c:"lav",tg:"Descrivi persone tipo concrete per progettare pensando a qualcuno, non a tutti.",d:1,
sp:"Una persona, nel senso del design, è un ritratto realistico di un utente tipo: un nome, un'età, una situazione, obiettivi, frustrazioni e abitudini. L'idea, resa popolare da Alan Cooper, è che progettare per «tutti» porta a progettare per nessuno. Avere in mente una persona concreta aiuta a prendere decisioni coerenti.",
ap:["Le personas funzionano se sono basate su osservazioni e interviste reali, non su stereotipi inventati. Di solito ne bastano due o tre per rappresentare i principali gruppi di utenti. Durante il lavoro ci si chiede: «Questa funzione servirebbe a Lucia, 68 anni, che usa il telefono solo per chiamare i nipoti?».","Puoi usarle anche fuori dal lavoro: per organizzare un evento (chi sono gli ospiti tipo?), scrivere un messaggio, aprire un'attività. Il limite è la semplificazione: le persone reali sono più varie delle personas."],
ri:[["Progettare per «tutti»","Nessuno si sente davvero servito."],["Discussioni astratte","Ognuno immagina un utente diverso."],["Prodotti troppo complicati","Si aggiunge ogni funzione possibile."]],
es:[["Lavoro","Una biblioteca crea tre personas: lo studente che cerca un posto tranquillo, la mamma con bambini piccoli, il pensionato che legge i giornali. Riorganizza gli spazi per ciascuno."],["Te stesso","Per il tuo corso di cucina immagini Marco, 30 anni, che non ha mai cucinato e ha poco tempo. Progetti ricette da 20 minuti."]],
ex:["Per un tuo progetto, crea una persona con nome, situazione, obiettivi e frustrazioni.","Basa la persona su almeno una conversazione con una persona reale.","Nella prossima decisione chiediti: cosa ne penserebbe la mia persona?"],
q:["Per chi esattamente sto progettando?","Cosa vuole e cosa la frustra?","La mia persona è basata su osservazioni reali?"],
er:"Inventare personas basate su stereotipi invece che su persone reali.",
qz:[["Cos'è una persona nel design?",["Un dipendente","Un ritratto realistico di un utente tipo","Un cliente reale","Un tipo di sondaggio"],1,"Aiuta a progettare per qualcuno di concreto."],["Perché progettare «per tutti» è un problema?",["Costa meno","Si finisce per non servire bene nessuno","È più facile","Non è un problema"],1,"Senza un destinatario preciso le scelte diventano vaghe."]]},

{t:"La tecnica del pomodoro",c:"app",tg:"Lavora 25 minuti concentrato, poi fai una pausa di 5.",d:1,
sp:"Francesco Cirillo inventò questa tecnica negli anni Ottanta usando un timer da cucina a forma di pomodoro. Si sceglie un compito, si imposta il timer a 25 minuti, si lavora senza interruzioni, poi si fa una pausa di 5 minuti. Dopo quattro pomodori si fa una pausa più lunga. Il metodo rende più facile iniziare e mantenere la concentrazione.",
ap:["Venticinque minuti sembrano pochi, quindi è più facile cominciare anche un compito noioso. Il timer crea un piccolo impegno e protegge dalle distrazioni: se ti viene in mente altro, lo annoti e ci pensi dopo. Le pause regolari evitano la stanchezza.","La durata si può adattare: alcuni preferiscono 50 minuti di lavoro e 10 di pausa. Contare i pomodori fatti aiuta anche a capire quanto tempo richiedono davvero le attività."],
ri:[["Difficoltà a iniziare","Il compito sembra troppo grande."],["Distrazioni continue","Ogni pochi minuti controlli il telefono."],["Stanchezza dopo ore","Lavori a lungo senza pause."]],
es:[["Studio","Una studentessa studia con quattro pomodori al pomeriggio. Finisce prima e ricorda di più."],["Casa","Per riordinare la cantina, ti impegni solo per un pomodoro al giorno. In una settimana è in ordine."]],
ex:["Fai oggi due pomodori su un compito che rimandi.","Durante il pomodoro, annota su un foglio le distrazioni invece di seguirle.","Conta quanti pomodori ti servono per un'attività ricorrente."],
q:["Qual è l'unico compito di questo pomodoro?","Cosa devo allontanare per non essere interrotto?","Sto facendo davvero le pause?"],
er:"Saltare le pause o interrompere il pomodoro per ogni messaggio.",
qz:[["Quanto dura un pomodoro classico?",["10 minuti","25 minuti","1 ora","2 ore"],1,"Seguito da 5 minuti di pausa."],["Cosa fare se durante il pomodoro ti viene in mente altro?",["Farlo subito","Annotarlo e occupartene dopo","Interrompere il timer","Ignorare il lavoro"],1,"Protegge la concentrazione."]]},

{t:"Le cinque forze di Porter",c:"eco",tg:"La redditività di un settore dipende da concorrenti, clienti, fornitori, sostituti e nuovi entranti.",d:3,
sp:"Michael Porter, professore di Harvard, ha individuato cinque forze che determinano quanto è redditizio un settore: la rivalità tra i concorrenti esistenti, il potere dei clienti, il potere dei fornitori, la minaccia di prodotti sostitutivi e la minaccia di nuovi concorrenti. Più queste forze sono forti, più è difficile guadagnare.",
ap:["Un settore con pochi concorrenti, clienti sparsi, molti fornitori, nessun sostituto facile e grandi barriere all'ingresso è molto redditizio. Uno con tanti concorrenti uguali, pochi grandi clienti e sostituti a portata di mano è difficile. Il modello aiuta a capire non solo i concorrenti diretti, ma tutte le forze che riducono i margini.","Puoi usarlo anche per valutare una professione: quanti fanno il tuo lavoro? I clienti possono facilmente scegliere altri? Esiste una tecnologia che potrebbe sostituirti? Quanto è facile per altri entrare nel tuo campo?"],
ri:[["Margini che scendono","Guadagni sempre meno pur lavorando di più."],["Clienti che dettano le condizioni","Pochi grandi clienti impongono i prezzi."],["Alternative facili","I clienti possono passare a soluzioni diverse."]],
es:[["Lavoro","Un piccolo produttore di formaggi vende tutto a un'unica catena di supermercati, che impone i prezzi. Apre la vendita diretta per ridurre il potere del cliente."],["Te stesso","Un traduttore valuta la minaccia dei traduttori automatici e si specializza in traduzioni legali, dove il sostituto è meno affidabile."]],
ex:["Per il tuo lavoro o attività, dai un voto da 1 a 5 a ciascuna delle cinque forze.","Individua la forza più pericolosa e un modo per ridurla.","Pensa a un possibile prodotto sostitutivo per ciò che offri."],
q:["Quanto è forte la concorrenza diretta?","Chi ha potere tra clienti e fornitori?","Cosa potrebbe sostituirmi, e quanto è facile entrare nel mio campo?"],
er:"Guardare solo i concorrenti diretti ignorando le altre quattro forze.",
qz:[["Quale NON è una delle cinque forze di Porter?",["Potere dei clienti","Minaccia dei sostituti","Simpatia del titolare","Minaccia di nuovi entranti"],2,"Le forze riguardano la struttura del settore."],["Un settore con pochi grandi clienti che impongono i prezzi è...",["Molto redditizio","Difficile, perché il potere dei clienti è alto","Senza concorrenza","Ideale"],1,"Il potere dei clienti riduce i margini."]]},

{t:"Il dilemma del prigioniero",c:"eco",tg:"Due persone che agiscono solo per sé possono finire peggio che se collaborassero.",d:3,
sp:"Due complici vengono arrestati e interrogati separatamente. Se entrambi tacciono, prendono una pena leggera. Se uno accusa l'altro e l'altro tace, chi accusa esce libero e l'altro prende una pena pesante. Se si accusano a vicenda, entrambi prendono una pena media. Per ciascuno conviene accusare, qualunque cosa faccia l'altro; ma così entrambi finiscono peggio che se avessero taciuto.",
ap:["Il dilemma, formalizzato negli anni Cinquanta, mostra un conflitto tra interesse individuale e collettivo. Si ritrova in molte situazioni reali: guerre dei prezzi, sfruttamento delle risorse comuni, corse agli armamenti, colleghi che non condividono informazioni.","Quando il gioco si ripete, le cose cambiano. Nei tornei di Robert Axelrod vinse una strategia semplice chiamata «colpo su colpo»: collabora alla prima mossa, poi fai ciò che l'altro ha fatto la volta precedente. La cooperazione nasce dalla ripetizione, dalla reputazione e dalla comunicazione."],
ri:[["Tutti agiscono per sé e tutti perdono","L'interesse individuale porta a un risultato peggiore per tutti."],["Sfiducia reciproca","Nessuno vuole essere il primo a collaborare."],["Rapporti ripetuti","Ci si rivedrà in futuro."]],
es:[["Lavoro","Due bar vicini potrebbero abbassare i prezzi per rubarsi i clienti, rovinandosi entrambi. Si accordano tacitamente sui prezzi e competono sulla qualità."],["Relazioni","In un condominio, ognuno risparmia non pulendo le parti comuni, e tutti vivono peggio. Un turno condiviso risolve il dilemma."]],
ex:["Individua una situazione in cui tu e altri agite per interesse personale e finite tutti peggio.","Proponi un primo passo di collaborazione in un rapporto che si ripete.","Pensa a una regola o accordo che potrebbe rendere conveniente collaborare."],
q:["Se tutti fanno come me, come finiamo?","Il rapporto si ripeterà nel tempo?","Quale accordo renderebbe conveniente collaborare?"],
er:"Collaborare sempre anche con chi approfitta continuamente.",
qz:[["Cosa mostra il dilemma del prigioniero?",["Collaborare è sempre sbagliato","Agire solo per sé può portare a un risultato peggiore per tutti","I prigionieri mentono","La polizia vince sempre"],1,"L'interesse individuale e collettivo divergono."],["Quale strategia ha vinto nei tornei di Axelrod?",["Tradire sempre","Colpo su colpo: collaborare all'inizio e poi rispondere come l'altro","Agire a caso","Non giocare"],1,"Semplice, cooperativa e reattiva."]]},

{t:"Prototipi",c:"lav",tg:"Costruisci una versione grezza per imparare prima di costruire quella vera.",d:1,
sp:"Un prototipo è una versione semplice ed economica di un'idea, fatta per provarla e imparare. Può essere di carta, cartone, un disegno, un finto sito, una prova di una giornata. I prototipi trasformano discussioni astratte in reazioni concrete: le persone non sanno dire cosa vogliono, ma sanno reagire a qualcosa che vedono e toccano.",
ap:["Un detto dei designer è «se un'immagine vale mille parole, un prototipo vale mille riunioni». Costruire presto fa emergere problemi che sulla carta non si vedono. Il prototipo deve essere abbastanza grezzo da poterlo buttare senza dispiacere: lo scopo è imparare, non impressionare.","Puoi prototipare quasi tutto: un nuovo arredamento con scatole di cartone, un discorso registrandolo, un orario familiare provandolo per una settimana, un regalo chiedendo un'opinione su un disegno."],
ri:[["Discussioni senza fine","Si parla di un'idea senza vederla."],["Progetti costosi falliti","Si è costruito tutto prima di provare."],["Reazioni inattese","Le persone non usano ciò che hai fatto come pensavi."]],
es:[["Casa","Prima di comprare un tavolo grande, segni le sue dimensioni sul pavimento con il nastro adesivo e ci vivi una settimana. Scopri che è troppo grande."],["Lavoro","Prima di stampare mille volantini, ne stampi dieci e li mostri a clienti diversi."]],
ex:["Scegli un'idea su cui stai discutendo e costruisci in un'ora un prototipo grezzo.","Mostralo a tre persone e annota le reazioni senza difenderlo.","Butta via il prototipo e scrivi cosa hai imparato."],
q:["Qual è la versione più grezza che posso costruire adesso?","Cosa voglio imparare da questo prototipo?","Sono pronto a buttarlo via?"],
er:"Rendere il prototipo così curato da affezionarsi e non volerlo cambiare.",
qz:[["Qual è lo scopo principale di un prototipo?",["Vendere subito","Imparare e provare un'idea prima di costruirla davvero","Essere perfetto","Decorare l'ufficio"],1,"Serve a raccogliere reazioni concrete."],["Come dovrebbe essere un buon prototipo iniziale?",["Costoso e curato","Grezzo e facile da buttare","Definitivo","Segreto"],1,"Così si cambia senza esitazione."]]},

{t:"Sicurezza psicologica",c:"evo",tg:"In un gruppo si impara solo se ci si sente liberi di parlare, chiedere e sbagliare.",d:2,
sp:"Amy Edmondson, docente a Harvard, definisce la sicurezza psicologica come la convinzione condivisa che in un gruppo si possa correre il rischio di parlare: fare domande, ammettere errori, proporre idee, dissentire, senza essere umiliati o puniti. Una ricerca di Google sui propri team ha trovato che era il fattore più importante per il loro successo.",
ap:["Edmondson scoprì che i reparti ospedalieri migliori segnalavano più errori, non meno: non perché sbagliassero di più, ma perché si sentivano liberi di dirlo, e così imparavano. Dove manca la sicurezza psicologica, le persone tacciono, i problemi si nascondono e crescono.","Sicurezza psicologica non significa essere sempre d'accordo o abbassare gli standard: significa poter discutere apertamente proprio per raggiungerli. Chi guida un gruppo può costruirla ammettendo i propri errori, facendo domande, ringraziando chi porta notizie scomode."],
ri:[["Silenzio nelle riunioni","Nessuno fa domande o obiezioni."],["Errori scoperti tardi","Nessuno li segnala per paura."],["Il capo parla sempre per primo","Gli altri si allineano."]],
es:[["Lavoro","Una responsabile apre ogni riunione chiedendo: «Cosa non sta funzionando?» e ringrazia chi risponde. Dopo un mese i problemi emergono molto prima."],["Famiglia","I genitori dicono ai figli che possono raccontare un errore senza essere puniti subito. I figli iniziano a parlare dei problemi a scuola."]],
ex:["Nella prossima riunione o incontro di famiglia, ammetti un tuo piccolo errore.","Ringrazia esplicitamente qualcuno che ti porta una cattiva notizia.","Fai una domanda aperta come «cosa mi sto perdendo?» e ascolta senza difenderti."],
q:["Le persone qui si sentono libere di dire che qualcosa non va?","Come reagisco quando qualcuno ammette un errore?","Cosa posso fare per rendere più facile parlare?"],
er:"Confondere la sicurezza psicologica con l'evitare ogni critica.",
qz:[["Cos'è la sicurezza psicologica?",["Un sistema di allarme","La convinzione che in un gruppo si possa parlare e sbagliare senza essere umiliati","Un contratto a tempo indeterminato","L'assenza di regole"],1,"Permette di imparare dagli errori."],["Perché i reparti migliori segnalavano più errori?",["Sbagliavano di più","Si sentivano liberi di dirlo e quindi imparavano","Avevano più personale","Per caso"],1,"Dove si può parlare, gli errori emergono."]]},

{t:"La matrice di Pugh",c:"rag",tg:"Confronta più opzioni con un riferimento, criterio per criterio.",d:2,
sp:"L'ingegnere Stuart Pugh ha ideato un metodo per scegliere tra più alternative. Si sceglie un'opzione di riferimento, si elencano i criteri importanti e si confronta ogni altra opzione con il riferimento: migliore (+), uguale (0) o peggiore (−). Sommando i segni, ed eventualmente dando un peso ai criteri, emergono le opzioni più forti.",
ap:["Il vantaggio è che non serve dare voti precisi: basta dire se un'opzione è meglio o peggio del riferimento, cosa più facile e meno arbitraria. Il metodo rende visibili i punti forti e deboli di ogni alternativa e spesso suggerisce di combinarle.","Funziona per scegliere un'auto, una casa, un fornitore o un progetto. Conviene fare la matrice con altre persone coinvolte, perché la discussione sui segni è spesso la parte più utile."],
ri:[["Molte opzioni simili","Non riesci a decidere."],["Criteri non dichiarati","Ognuno sceglie per motivi diversi."],["Opinioni contrastanti","Il gruppo non trova un accordo."]],
es:[["Casa","Confronti tre appartamenti con quello in cui vivi ora come riferimento, su prezzo, distanza dal lavoro, luce, spazio. Uno ottiene molti più + degli altri."],["Lavoro","Il gruppo confronta quattro fornitori con quello attuale. La discussione sui criteri chiarisce cosa conta davvero."]],
ex:["Per una scelta in corso, scegli un'opzione di riferimento ed elenca cinque criteri.","Confronta ogni alternativa con +, 0 o −.","Prova a combinare i punti forti delle due migliori opzioni."],
q:["Qual è il mio riferimento?","Quali criteri contano davvero?","Posso combinare i punti forti di più opzioni?"],
er:"Dare a tutti i criteri lo stesso peso quando alcuni contano molto di più.",
qz:[["Come si confrontano le opzioni nella matrice di Pugh?",["Con voti da 1 a 100","Con +, 0 o − rispetto a un riferimento","Con il prezzo e basta","A caso"],1,"Si confronta con un'opzione di riferimento."],["Qual è un vantaggio del metodo?",["Elimina il giudizio","Rende visibili punti forti e deboli e facilita la discussione","È velocissimo","Sceglie da solo"],1,"Chiarisce i criteri e le differenze."]]},

{t:"Schiettezza accompagnata da cura",c:"com",tg:"Dì le cose come stanno, perché ti importa della persona.",d:2,
sp:"Kim Scott, ex dirigente di Google e Apple, ha chiamato questo approccio «franchezza radicale»: unire l'interesse sincero per la persona con il coraggio di dirle la verità. Senza cura, la franchezza diventa aggressività. Senza franchezza, la cura diventa una gentilezza vigliacca che lascia l'altro nell'errore. Il punto è avere entrambe.",
ap:["Scott descrive quattro stili: franchezza radicale (cura + sincerità), aggressività odiosa (sincerità senza cura), empatia rovinosa (cura senza sincerità) e falsità manipolatoria (né cura né sincerità). Molte persone gentili cadono nell'empatia rovinosa: per non ferire, non dicono nulla, e l'altro continua a sbagliare.","Per praticarla: dai riscontri presto, in privato quando sono critiche, specifici e orientati a migliorare. E chiedi anche tu riscontri sinceri, accettandoli senza difenderti."],
ri:[["Tacere per non ferire","L'altro non sa cosa migliorare."],["Critiche dure e pubbliche","La persona si chiude."],["Complimenti vaghi","«Bravo» senza dire cosa."]],
es:[["Lavoro","Una manager dice in privato a un collaboratore: «Ci tengo che la tua presentazione vada bene. Le slide sono troppo piene: proviamo a tenere un messaggio per slide?»."],["Amicizia","Un amico ti chiede un parere sul suo progetto di aprire un bar. Gli dici con affetto quali rischi vedi nei numeri, invece di incoraggiarlo e basta."]],
ex:["Pensa a un riscontro che stai rimandando per gentilezza e preparalo in modo specifico e utile.","Chiedi a una persona di fiducia: «Cosa potrei fare meglio?» e ascolta senza giustificarti.","Sostituisci un complimento vago con uno specifico."],
q:["Sto tacendo per proteggere l'altro o me stesso?","Questo riscontro mostra che mi importa della persona?","È specifico e utile per migliorare?"],
er:"Usare la «franchezza» come scusa per essere brutali.",
qz:[["Cos'è l'empatia rovinosa secondo Kim Scott?",["Essere troppo sinceri","Essere gentili al punto di non dire ciò che servirebbe","Manipolare","Urlare"],1,"Per non ferire, si lascia l'altro nell'errore."],["Quali due elementi unisce la franchezza radicale?",["Potere e controllo","Cura per la persona e sincerità diretta","Velocità e precisione","Lodi e premi"],1,"Servono entrambi."]]},

{t:"Ridurre il rimpianto futuro",c:"rag",tg:"Immagina di avere 80 anni e chiediti cosa rimpiangeresti di più.",d:1,
sp:"Jeff Bezos racconta di aver deciso di lasciare un lavoro sicuro per fondare Amazon usando un metodo semplice: immaginò di avere 80 anni e si chiese quale scelta avrebbe minimizzato i rimpianti. Capì che non si sarebbe pentito di aver provato e fallito, ma che si sarebbe pentito di non averci provato. Il modello aiuta nelle decisioni importanti della vita.",
ap:["Le ricerche dello psicologo Thomas Gilovich mostrano che nel breve periodo rimpiangiamo di più le azioni sbagliate, ma nel lungo periodo rimpiangiamo soprattutto ciò che non abbiamo fatto. Guardare la decisione da molto lontano toglie peso alle paure del momento e mette in luce ciò che conta.","Il metodo è utile per scelte grandi e personali: cambiare lavoro, trasferirsi, iniziare un progetto, riallacciare un rapporto. Non sostituisce il buon senso: alcuni rischi sono troppo grandi, e va valutato anche il rimpianto di aver rischiato troppo."],
ri:[["Scelte di vita importanti","Lavoro, casa, relazioni, progetti."],["Paura che blocca","Rimandi per timore di fallire."],["«Un giorno lo farò»","Sogni rimandati da anni."]],
es:[["Lavoro","Una persona sogna di aprire un laboratorio di falegnameria. Immaginandosi a 80 anni, capisce che rimpiangerebbe di non averci provato. Inizia nei weekend."],["Relazioni","Non senti un vecchio amico da anni per orgoglio. Ti chiedi se a 80 anni rimpiangeresti di non averlo chiamato. Lo chiami."]],
ex:["Scrivi una decisione importante in sospeso e immagina di raccontarla a 80 anni.","Elenca tre cose che rimpiangeresti di non aver fatto.","Scegli un piccolo passo verso una di queste cose."],
q:["A 80 anni, cosa rimpiangerei di più?","Rimpiangerei di aver provato o di non averlo fatto?","Questo rischio è sostenibile?"],
er:"Usare il modello per giustificare rischi sconsiderati.",
qz:[["Cosa rimpiangiamo di più nel lungo periodo secondo le ricerche?",["Le azioni sbagliate","Ciò che non abbiamo fatto","I soldi spesi","Nulla"],1,"Nel tempo pesano di più le occasioni mancate."],["Come si usa il modello?",["Pensando alla prossima settimana","Immaginando di avere 80 anni e chiedendosi cosa si rimpiangerebbe","Chiedendo agli amici","Lanciando una moneta"],1,"La distanza chiarisce ciò che conta."]]},

{t:"Il rendimento del fallimento",c:"app",tg:"Ogni fallimento produce qualcosa di utile, se sai raccoglierlo.",d:2,
sp:"Un fallimento ha un costo, ma può anche dare un rendimento: lezioni apprese, competenze nuove, contatti, materiali, dati su cosa non funziona. Il modello ti invita, dopo un insuccesso, a fare un inventario di ciò che hai ottenuto oltre alla perdita, così che il prezzo pagato non vada sprecato.",
ap:["Molte storie di successo nascono da fallimenti precedenti: un prodotto che non vende rivela un bisogno diverso, un'azienda chiusa lascia competenze per la successiva. Il fallimento però rende solo se lo si analizza: se lo si nasconde o lo si dimentica, si paga il costo senza incassare il rendimento.","Per usarlo, dopo un insuccesso scrivi: cosa ho imparato, cosa so fare ora che prima non sapevo, chi ho conosciuto, cosa posso riutilizzare. E per ridurre i costi, fallisci in piccolo e presto, con esperimenti a basso rischio."],
ri:[["Fallimenti dimenticati in fretta","Non vuoi più pensarci."],["Stessi errori ripetuti","Non hai estratto la lezione."],["Paura di provare","Vedi solo il costo del fallimento."]],
es:[["Lavoro","Un negozio online chiude dopo un anno. Il titolare scopre di aver imparato marketing, fotografia e gestione dei fornitori. Usa queste competenze per un nuovo lavoro ben pagato."],["Te stesso","Un esame non superato ti mostra che il metodo di studio non funziona. Lo cambi per tutti gli esami successivi."]],
ex:["Scegli un fallimento passato e scrivi cinque cose che ti ha lasciato.","Dopo il prossimo insuccesso, fai l'inventario entro una settimana.","Progetta un piccolo esperimento in cui fallire costi poco."],
q:["Cosa ho imparato da questo fallimento?","Cosa posso riutilizzare?","Come posso fallire in piccolo la prossima volta?"],
er:"Raccontarsi che ogni fallimento è positivo per evitare di sentirne il peso.",
qz:[["Quando un fallimento produce un rendimento?",["Sempre, automaticamente","Quando lo si analizza e se ne estraggono lezioni e risorse","Mai","Quando lo si nasconde"],1,"Serve raccogliere ciò che ha lasciato."],["Come ridurre il costo dei fallimenti?",["Non provare mai","Fallire in piccolo e presto con esperimenti a basso rischio","Rischiare tutto","Ignorarli"],1,"Piccoli fallimenti costano poco e insegnano molto."]]},

{t:"Il punteggio RICE",c:"lav",tg:"Dai priorità ai progetti con portata, impatto, fiducia e sforzo.",d:2,
sp:"Il punteggio RICE, nato nell'azienda Intercom, aiuta a ordinare idee e progetti. Per ciascuno si stimano quattro valori: Portata (Reach: quante persone tocca in un periodo), Impatto (quanto cambia per ciascuna), Fiducia (Confidence: quanto sei sicuro delle stime) ed Effort (quanto lavoro richiede). Il punteggio è portata × impatto × fiducia, diviso lo sforzo.",
ap:["Il fattore fiducia è la parte più originale: un'idea con stime entusiaste ma poche prove viene penalizzata, e questo protegge dalle idee del cuore. Lo sforzo al denominatore favorisce i progetti che danno molto con poco.","Puoi usarlo in forma semplice anche per la vita personale: quale progetto di casa, studio o volontariato tocca più persone, conta di più, è più sicuro e costa meno? I numeri sono stime, ma obbligano a ragionare in modo esplicito."],
ri:[["Troppe idee in competizione","Non sai quale fare prima."],["Scelte guidate dall'entusiasmo","Vince chi parla più forte."],["Progetti costosi poco utili","Molto sforzo per pochi."]],
es:[["Lavoro","Un piccolo comune valuta tre progetti: wifi in biblioteca, nuova app, panchine al parco. Il calcolo RICE mostra che il wifi tocca più persone con meno sforzo."],["Casa","Tra rifare il bagno, montare tende oscuranti e sistemare il giardino, le tende vincono: tutti dormono meglio con poco sforzo."]],
ex:["Elenca cinque idee o progetti e stima per ciascuno portata, impatto, fiducia e sforzo.","Calcola il punteggio e ordina la lista.","Controlla l'idea con la fiducia più bassa: come puoi raccogliere più prove?"],
q:["Quante persone tocca?","Quanto cambia per ciascuna, e quanto ne sono sicuro?","Quanto lavoro richiede?"],
er:"Credere che il punteggio sia preciso: è un aiuto a ragionare, non una verità.",
qz:[["Cosa rappresenta la C di RICE?",["Costo","Fiducia nelle stime","Clienti","Calendario"],1,"Penalizza le idee con poche prove."],["Come si calcola il punteggio RICE?",["Portata + impatto","Portata × impatto × fiducia ÷ sforzo","Sforzo × costo","Impatto − fiducia"],1,"Lo sforzo sta al denominatore."]]},

{t:"La matrice dei rischi",c:"qua",tg:"Valuta ogni rischio per probabilità e gravità, e affronta prima quelli in alto a destra.",d:1,
sp:"La matrice dei rischi è una griglia con due assi: quanto è probabile che un evento accada e quanto sarebbe grave. Ogni rischio viene posizionato nella griglia. Quelli probabili e gravi vanno affrontati subito; quelli improbabili e lievi si possono accettare; gli altri richiedono attenzione o un piano di riserva.",
ap:["Lo strumento è usato in sicurezza sul lavoro, progetti, sanità, finanza. Il suo valore è costringere a pensare a due dimensioni separate: tendiamo a preoccuparci di eventi gravi ma rarissimi e a ignorare quelli meno spettacolari ma frequenti.","Per ogni rischio importante si può scegliere una strategia: evitarlo, ridurlo, trasferirlo (ad esempio con un'assicurazione) o accettarlo consapevolmente. Attenzione agli eventi molto rari ma catastrofici: anche se improbabili, possono meritare protezione."],
ri:[["Paure sproporzionate","Ti preoccupi di eventi rarissimi."],["Rischi frequenti ignorati","I piccoli problemi quotidiani sono trascurati."],["Progetti senza piano B","Nessuno ha pensato a cosa potrebbe andare storto."]],
es:[["Viaggi","Per un viaggio elenchi i rischi: smarrimento bagagli, malattia, sciopero. Prendi un'assicurazione sanitaria (gravità alta) e accetti il rischio del bagaglio portando un cambio nello zaino."],["Lavoro","Il gruppo scopre che il rischio più probabile e grave è la malattia dell'unica persona che conosce il sistema. Forma una seconda persona."]],
ex:["Per un progetto o un viaggio, elenca dieci rischi e posizionali nella griglia.","Per i due rischi più alti scegli una strategia: evitare, ridurre, trasferire o accettare.","Controlla se ti stai preoccupando di un rischio rarissimo e trascurando uno frequente."],
q:["Quanto è probabile?","Quanto sarebbe grave?","Lo evito, lo riduco, lo trasferisco o lo accetto?"],
er:"Ignorare i rischi rari ma catastrofici perché la probabilità è bassa.",
qz:[["Quali sono i due assi della matrice dei rischi?",["Costo e tempo","Probabilità e gravità","Persone e luoghi","Passato e futuro"],1,"Si valutano separatamente."],["Cosa significa trasferire un rischio?",["Ignorarlo","Passarne le conseguenze a qualcun altro, ad esempio con un'assicurazione","Raddoppiarlo","Eliminarlo del tutto"],1,"L'assicurazione è l'esempio tipico."]]},

{t:"Mettere alla prova l'ipotesi più rischiosa",c:"lav",tg:"Verifica per prima la supposizione che, se sbagliata, farebbe crollare tutto.",d:2,
sp:"Ogni progetto si basa su supposizioni: che le persone abbiano quel problema, che siano disposte a pagare, che la tecnologia funzioni, che i tempi siano realistici. Alcune sono più rischiose di altre: se sono sbagliate, il progetto crolla. Il modello ti chiede di individuare quella più rischiosa e verificarla per prima, nel modo più economico possibile.",
ap:["Tendiamo a lavorare sulle parti che ci piacciono o che sappiamo fare, lasciando per ultime le domande scomode. Così si spendono mesi su un progetto basato su un'ipotesi mai verificata. Gli esperti di innovazione chiamano questo approccio «test delle ipotesi più rischiose».","Per usarlo: elenca le supposizioni, valuta per ciascuna quanto è incerta e quanto sarebbe grave se fosse falsa, scegli quella più incerta e importante, e progetta un test rapido. Se il test va male, hai risparmiato tempo e soldi."],
ri:[["Progetti basati su «sicuramente»","Si dà per scontato che le persone vogliano qualcosa."],["Lavoro sulle parti facili","Si rimandano le domande scomode."],["Grandi investimenti iniziali","Si spende prima di sapere."]],
es:[["Lavoro","Prima di aprire un servizio di lezioni di yoga per anziani, verifichi l'ipotesi più rischiosa: verranno? Organizzi una lezione gratuita nella sala del quartiere."],["Te stesso","Vuoi trasferirti all'estero. L'ipotesi più rischiosa è che tu trovi lavoro. Fai colloqui online prima di vendere casa."]],
ex:["Per un tuo progetto, elenca cinque supposizioni.","Scegli quella più incerta e più importante.","Progetta un test che duri meno di due settimane e costi poco."],
q:["Quale supposizione, se sbagliata, farebbe crollare tutto?","Quanto sono sicuro che sia vera?","Qual è il modo più rapido ed economico per verificarla?"],
er:"Verificare per prime le ipotesi facili perché danno risultati rassicuranti.",
qz:[["Quale ipotesi va verificata per prima?",["La più facile","Quella che, se sbagliata, farebbe crollare il progetto","La più divertente","Nessuna"],1,"Si riduce subito il rischio maggiore."],["Perché tendiamo a rimandare le ipotesi rischiose?",["Sono poche","Perché sono scomode e preferiamo lavorare sulle parti piacevoli","Perché sono già verificate","Non le rimandiamo"],1,"Le domande scomode fanno paura."]]},

{t:"Rolestorming: pensare da un altro ruolo",c:"com",tg:"Genera idee immaginando di essere un'altra persona.",d:1,
sp:"Il rolestorming è una variante del brainstorming in cui, invece di proporre idee come te stesso, immagini di essere qualcun altro: un cliente, un concorrente, un bambino, un personaggio famoso, il tuo capo. Parlare da un altro ruolo riduce la paura del giudizio e apre punti di vista che da soli non vedremmo.",
ap:["La tecnica, proposta da Rick Griggs, funziona perché togliamo pressione all'idea: non è nostra, è «del personaggio». Questo aiuta le persone timide e quelle bloccate nelle proprie abitudini. Inoltre, immedesimarsi in qualcuno con interessi diversi rivela bisogni e obiezioni nascosti.","Puoi usarlo da solo o in gruppo. Chiediti: cosa proporrebbe un bambino di dieci anni? Come lo risolverebbe un'azienda famosa per il servizio clienti? Cosa direbbe il nostro cliente più esigente?"],
ri:[["Idee sempre uguali","Il gruppo produce le solite proposte."],["Persone che non parlano","Qualcuno teme il giudizio."],["Punto di vista unico","Vedi il problema solo dal tuo ruolo."]],
es:[["Lavoro","Il gruppo di una palestra immagina di essere una persona sovrappeso che entra per la prima volta. Nascono idee per un ingresso più accogliente."],["Famiglia","Per organizzare le vacanze, ognuno propone idee come se fosse il nonno. Escono attività adatte a tutte le età."]],
ex:["Su un problema attuale, scrivi tre idee come se fossi tre persone diverse.","In una riunione, proponi di dedicare dieci minuti al rolestorming.","Immagina come il tuo concorrente cercherebbe di battere la tua idea."],
q:["Come lo vedrebbe un'altra persona?","Cosa proporrebbe qualcuno molto diverso da me?","Quali obiezioni farebbe chi sta dall'altra parte?"],
er:"Usare personaggi stereotipati che non aggiungono vere prospettive.",
qz:[["Cosa si fa nel rolestorming?",["Si gioca di ruolo per divertimento","Si generano idee immaginando di essere un'altra persona","Si assegnano ruoli di lavoro","Si fa teatro"],1,"Il ruolo apre nuovi punti di vista."],["Perché aiuta le persone timide?",["Perché parlano meno","Perché l'idea è «del personaggio» e la paura del giudizio cala","Perché è obbligatorio","Non le aiuta"],1,"Si toglie pressione all'idea."]]},

{t:"La regola del tre",c:"com",tg:"Le cose presentate in gruppi di tre si ricordano e convincono di più.",d:1,
sp:"«Veni, vidi, vici», «libertà, uguaglianza, fraternità», «sangue, fatica, lacrime e sudore» ridotto nella memoria a tre parole. Le liste di tre elementi sono abbastanza brevi da ricordare e abbastanza lunghe da creare un ritmo e un senso di completezza. La regola del tre suggerisce di organizzare messaggi, discorsi e argomenti in gruppi di tre.",
ap:["Il nostro cervello riconosce facilmente gli schemi, e tre è il numero minimo per formarne uno. Due elementi sembrano un confronto, quattro iniziano a confondere. Molte storie hanno tre atti, molte barzellette tre personaggi, molti slogan tre parole.","Per usarla: tre messaggi chiave in una presentazione, tre ragioni in una proposta, tre esempi per spiegare un'idea. Non forzare: se le cose importanti sono due o cinque, non inventarne o toglierne per arrivare a tre."],
ri:[["Messaggi difficili da ricordare","Troppi punti diversi."],["Presentazioni senza struttura","Il pubblico si perde."],["Liste lunghissime","Dieci ragioni dove ne bastano tre."]],
es:[["Lavoro","Una presentazione di 20 slide viene riorganizzata in tre messaggi: il problema, la soluzione, il costo. Tutti la ricordano."],["Famiglia","Ai bambini date tre regole per la casa invece di dieci. Le rispettano molto di più."]],
ex:["Riassumi il tuo lavoro o progetto in tre parole o frasi.","Nella prossima richiesta importante, scegli le tre ragioni più forti.","Rileggi un tuo testo lungo e riorganizzalo in tre parti."],
q:["Quali sono i tre punti più importanti?","Posso togliere ciò che va oltre?","Le tre parti hanno un ritmo e un ordine chiaro?"],
er:"Forzare ogni contenuto in tre parti anche quando non è naturale.",
qz:[["Perché le liste di tre funzionano bene?",["Sono obbligatorie","Sono facili da ricordare e danno ritmo e completezza","Sono più lunghe","Per superstizione"],1,"Tre è il minimo per creare uno schema."],["Cosa fare se le cose importanti sono cinque?",["Toglierne due a caso","Non forzarle per forza in tre","Inventarne un'altra","Nasconderle"],1,"La regola è un aiuto, non un obbligo."]]},

{t:"Satisficing: una scelta abbastanza buona",c:"rag",tg:"Scegli la prima opzione che soddisfa i tuoi criteri invece di cercare la migliore in assoluto.",d:1,
sp:"L'economista e premio Nobel Herbert Simon ha unito le parole inglesi «satisfy» e «suffice» per descrivere una strategia: invece di cercare l'opzione migliore possibile (massimizzare), si fissano dei criteri e si sceglie la prima opzione che li soddisfa. Le ricerche di Barry Schwartz mostrano che chi si accontenta in questo modo è spesso più felice di chi cerca sempre il massimo.",
ap:["Cercare l'opzione perfetta richiede tempo, energia e informazioni che spesso non abbiamo. E alla fine i massimizzatori tendono a essere meno soddisfatti, perché pensano sempre alle alternative scartate. Il satisficing non significa accontentarsi di poco: i criteri possono essere alti, ma una volta raggiunti si smette di cercare.","Conviene massimizzare nelle poche decisioni davvero importanti e irreversibili, e scegliere «abbastanza buono» in tutte le altre: ristorante, maglione, cellulare, vacanza."],
ri:[["Ricerca infinita","Continui a cercare anche dopo aver trovato qualcosa di buono."],["Rimpianto dopo ogni scelta","Pensi sempre che ci fosse di meglio."],["Fatica nelle piccole decisioni","Passi un'ora a scegliere un ristorante."]],
es:[["Acquisti","Per un nuovo telefono fissi tre criteri: batteria che dura un giorno, buona fotocamera, meno di 400 euro. Compri il primo che li soddisfa."],["Casa","Cerchi un'idraulico: deve essere disponibile questa settimana e avere buone recensioni. Chiami il primo che le ha."]],
ex:["Per la prossima piccola decisione, scrivi tre criteri e scegli la prima opzione che li soddisfa.","Individua una decisione in cui stai cercando il meglio quando basterebbe il buono.","Dopo la scelta, smetti di confrontare con le alternative."],
q:["Quali criteri deve soddisfare?","Questa scelta merita la ricerca del meglio assoluto?","Ho già trovato qualcosa di abbastanza buono?"],
er:"Accontentarsi di poco anche nelle decisioni davvero importanti.",
qz:[["Cosa significa satisficing?",["Cercare sempre il massimo","Scegliere la prima opzione che soddisfa criteri prefissati","Non scegliere mai","Scegliere a caso"],1,"Si smette di cercare quando i criteri sono raggiunti."],["Quando conviene massimizzare invece?",["In tutte le scelte","Nelle poche decisioni davvero importanti e irreversibili","Mai","Al ristorante"],1,"Lì lo sforzo in più vale la pena."]]},

{t:"Il modello SCARF",c:"evo",tg:"Status, certezza, autonomia, relazione ed equità: cinque bisogni sociali che, se minacciati, scatenano reazioni forti.",d:2,
sp:"David Rock, studioso di neuroscienze applicate al lavoro, ha proposto il modello SCARF: cinque aspetti sociali che il cervello tratta quasi come questioni di sopravvivenza. Status (la propria importanza rispetto agli altri), Certezza (sapere cosa succederà), Autonomia (sentire di avere scelta), Relazione (sentirsi al sicuro con gli altri) ed Equità (percepire che le cose sono giuste). Quando uno è minacciato, reagiamo in difesa.",
ap:["Molti conflitti sul lavoro e in famiglia nascono da minacce a questi bisogni, anche involontarie. Un riscontro critico può minacciare lo status; un cambiamento improvviso la certezza; un ordine senza spiegazioni l'autonomia; una decisione percepita come ingiusta l'equità.","Per usarlo, prima di una conversazione o di un cambiamento chiediti quale dei cinque bisogni potrebbe essere toccato e come proteggerlo: dare informazioni (certezza), offrire scelte (autonomia), spiegare i criteri (equità), riconoscere il valore della persona (status)."],
ri:[["Reazioni sproporzionate","Una frase innocua provoca rabbia."],["Resistenza ai cambiamenti","Le persone si oppongono senza motivi chiari."],["Sensazione di ingiustizia","Qualcuno si sente trattato in modo diverso."]],
es:[["Lavoro","Un responsabile annuncia un nuovo orario. Spiega perché (certezza), lascia scegliere tra due turni (autonomia) e applica le stesse regole a tutti (equità). Le proteste sono poche."],["Famiglia","Un figlio si arrabbia per una correzione davanti agli amici: minaccia allo status. La volta dopo lo dici in privato."]],
ex:["Ripensa a una tua reazione forte recente: quale dei cinque bisogni era minacciato?","Prima di comunicare un cambiamento, scrivi come proteggere ciascuno dei cinque.","In una conversazione difficile, offri all'altro almeno una scelta."],
q:["Quale bisogno potrebbe sentirsi minacciato?","Come posso dare più certezza, autonomia o equità?","Sto facendo sentire l'altro meno importante?"],
er:"Pensare che le reazioni emotive siano irrazionali invece di capirne la causa.",
qz:[["Cosa significa la A di SCARF?",["Ambizione","Autonomia","Affetto","Attenzione"],1,"Il bisogno di avere una scelta."],["Un cambiamento annunciato all'improvviso minaccia soprattutto...",["Lo status","La certezza","La relazione","Nessun bisogno"],1,"Non sapere cosa succederà crea allarme."]]},

{t:"Scrum",c:"lav",tg:"Lavora in cicli brevi con obiettivi chiari, incontri brevi quotidiani e revisioni regolari.",d:2,
sp:"Scrum è un metodo per lavorare in squadra su progetti complessi, nato nello sviluppo software e ideato da Jeff Sutherland e Ken Schwaber. Il lavoro si divide in cicli di una o due settimane, chiamati sprint. Ogni sprint ha un obiettivo, una breve riunione quotidiana per coordinarsi, una revisione del risultato con chi lo usa e una retrospettiva per migliorare il modo di lavorare.",
ap:["I ruoli principali sono il responsabile del prodotto, che decide le priorità, il facilitatore (scrum master), che aiuta la squadra a lavorare bene e rimuove gli ostacoli, e la squadra di sviluppo. Il nome viene dalla mischia del rugby, dove la squadra avanza insieme.","Le idee di Scrum funzionano anche fuori dal software: una famiglia che organizza la settimana con un breve incontro domenicale e una revisione il venerdì, un gruppo di studio che lavora in cicli di due settimane con obiettivi chiari."],
ri:[["Progetti lunghi senza tappe","Non si vede quando si arriva."],["Squadra scoordinata","Nessuno sa cosa fanno gli altri."],["Stessi problemi ogni volta","Non ci si ferma a migliorare il metodo."]],
es:[["Lavoro","Un gruppo di marketing lavora in sprint di due settimane: ogni mattina 15 minuti in piedi, ogni due venerdì una revisione con il cliente e una retrospettiva."],["Famiglia","La domenica sera la famiglia sceglie tre obiettivi per la settimana e il venerdì controlla cosa ha funzionato."]],
ex:["Organizza le prossime due settimane come uno sprint con un obiettivo chiaro.","Prova un incontro quotidiano di 10 minuti con chi lavora con te: cosa ho fatto, cosa farò, cosa mi blocca.","Alla fine dello sprint, fai una retrospettiva: cosa teniamo, cosa cambiamo."],
q:["Qual è l'obiettivo di questo ciclo?","Cosa mi blocca oggi?","Cosa miglioriamo nel modo di lavorare?"],
er:"Seguire i rituali di Scrum senza lo spirito di imparare e adattarsi.",
qz:[["Cos'è uno sprint in Scrum?",["Una corsa","Un ciclo di lavoro breve con un obiettivo","Una riunione annuale","Un premio"],1,"Di solito dura una o due settimane."],["A cosa serve la retrospettiva?",["A festeggiare","A migliorare il modo di lavorare della squadra","A valutare i singoli","A pianificare l'anno"],1,"Si riflette sul processo, non solo sul risultato."]]}
);
